result_preview:
{
    "场景描述": "中式鲜活大闸蟹",
    "整体引导": "让螃蟹靠碗边。镜头贴近碗沿。降低机位微俯。对焦青色蟹壳。",
    "摆盘描述": "保持碗底留白。把螃蟹移到侧边。蟹钳朝向前方。展现蟹壳质感。"
}

{
    "场景描述": "铜锅火锅涮肉",
    "整体引导": "羊肉铺在碎冰上面。单手拿筷子夹肉。向斜下方微俯拍。",
    "摆盘描述": "羊肉卷整齐铺冰上。多肉植物摆在前方。标牌插在右后侧。"
}

{
    "场景描述": "韩餐冷面配泡菜",
    "整体引导": "移走杂物。泡菜放后方。降低角度近距离拍。用筷子夹起冷面。",
    "摆盘描述": "移走周围多余碗盘。泡菜放冷面右上角。将半颗鸡蛋露出来。"
}

{
    "场景描述": "暗调川味红汤锅",
    "整体引导": "加满红汤底。换暗背景打顶光。相机降至平视。聚焦锅体正面。",
    "摆盘描述": "加满红油汤底。让食材微露表面。擦净锅体边缘。露出中间立柱。"
}

{
    "场景描述": "街边铁盘烤海鲜",
    "整体引导": "拿掉塑料袋，镜头贴近烤串，斜向下微距拍，虚化后方背景。",
    "摆盘描述": "撤掉塑料袋，将三根烤串靠拢，呈对角线叠放，突出中间葱段。"
}

{
    "场景描述": "暗调川味红油锅",
    "整体引导": "压低视角近景拍摄。对焦居中的小铜锅。汤勺贴近平稳注油。",
    "摆盘描述": "小铜锅居中。外圈铺满红辣椒。压低汤勺，倒出粗实连贯油柱。"
}

{
    "场景描述": "泰式冬阴功汤面",
    "整体引导": "将绿饮放在最前方。降至四十五度拍摄。筷子夹面停在锅上方。",
    "摆盘描述": "虾与煎蛋放面条表层。配菜盘围着金锅摆放。降低筷子夹面高度。"
}

{
    "场景描述": "火锅店生鲜菜品",
    "整体引导": "降四十五度俯拍，牛蛙移左下，毛肚放正中，大光圈虚化后景。",
    "摆盘描述": "牛蛙盘移至左下角，毛肚方盘放中间，酱料盘推至右后方。"
}

{
    "场景描述": "白桌韩式冷面",
    "整体引导": "放下筷子和面，整理表面食材，镜头稍后退，向下俯视拍摄。",
    "摆盘描述": "面条放回汤中。牛肉平铺中间。泡菜聚拢左侧。冰块点缀右侧。"
}

{
    "场景描述": "火锅肉片与蔬菜",
    "整体引导": "将肉盘放在正中间。蔬菜盒推向后方。降低机位贴近肉片拍。",
    "摆盘描述": "将肉盘移至正中央。火锅底放在右下角。蔬菜盒推向最后方。"
}

{
    "场景描述": "街头炭火烤肉串",
    "整体引导": "抓起几根肉串，斜向上举起。镜头靠近拍摄，虚化背景炉火。",
    "摆盘描述": "挑出五根肉串，顶部肉块聚拢。呈对角线举起，底部竹签散开。"
}

{
    "场景描述": "韩式冷面配沙拉",
    "整体引导": "冷面放正前方。沙拉放左后方。右手用筷夹面。向下倾斜俯拍。",
    "摆盘描述": "面条盘碗中央。番茄黄瓜贴边。泡菜堆放右侧。香菜点缀表面。"
}

{
    "场景描述": "韩式烤肉配蘸料",
    "整体引导": "筷子夹起烤肉。降低相机视角。贴近肉片对焦。虚化后方景物。",
    "摆盘描述": "烤肉堆在盘中。蘸料碟放后方。筷子夹起一块肉。举在盘子上方。"
}

{
    "场景描述": "韩式拌饭木桌景",
    "整体引导": "小菜碟放左下。大碗向后方推。降低手机机位。四十五度斜拍。",
    "摆盘描述": "清空桌面杂物。小菜碟放左前方。大碗移至右后方。拉开碟碗距离。"
}

{
    "场景描述": "日式餐厅寿司盘",
    "整体引导": "镜头向后退。四十五度俯拍。竹杯放在左侧。拍出完整黑盘。",
    "摆盘描述": "长盘斜放在正中。刺身碗放左后方。竹杯摆在左侧。露出大理石。"
}

{
    "场景描述": "老北京铜锅涮肉",
    "整体引导": "降低机位平拍。镜头贴近羊肉。逆光突出烟雾。把肉举高一点。",
    "摆盘描述": "筷子夹起羊肉。折叠肉片造层次。悬停在铜锅上方。远离水面。"
}

{
    "场景描述": "美式快餐脆炸鸡",
    "整体引导": "将炸鸡块居中叠放。降低镜头微侧平拍。大光圈虚化背景。",
    "摆盘描述": "炸鸡在垫纸居中。底部紧凑平铺。顶部交叉叠放。增加立体高度。"
}

{
    "场景描述": "韩餐馆辣鸡爪",
    "整体引导": "手机放低并靠近。用筷子高举鸡爪。对准鸡爪对焦，虚化背景。",
    "摆盘描述": "挑选一个完整的鸡爪。在碗的左侧边缘，垫一片新鲜大绿叶。"
}

{
    "场景描述": "中式烧烤夜宵桌",
    "整体引导": "将两根肉串悬空举起。镜头靠近肉串特写。开启大光圈虚化。",
    "摆盘描述": "将烤青椒放左下角。挑出两根肉串举起。其余烤串铺在盘中。"
}

{
    "场景描述": "室内木桌海鲜照",
    "整体引导": "将包装置于木桌。左手扶稳。开启大光圈。虚化背景。正面平拍。",
    "摆盘描述": "抹平包装避免反光。底部垂直立于木桌。左手轻捏袋子左侧。"
}

{
    "场景描述": "日式刺身拼盘",
    "整体引导": "刺身居中，花朵放边缘。镜头微上移俯拍，拍全右上角酱碟。",
    "摆盘描述": "紫苏叶垫底，刺身交叠放中间。左下角摆放红花，旁边点缀芥末。"
}

{
    "场景描述": "木桌火锅生牛肉",
    "整体引导": "蘸料放左下作前景。降低镜头至四十五度。靠近对焦生牛肉。",
    "摆盘描述": "蘸料碗移至左下角。背景保留毛肚酒瓶。整体移至木纹桌面。"
}

{
    "场景描述": "韩式烤肉聚餐。",
    "整体引导": "生牛肉放近前。烤炉置于后方。用夹子烤肉。平拍虚化后背景。",
    "摆盘描述": "生肉柠檬放铁盘。香菇置于右侧。绿叶做点缀。铁盘置最前方。"
}

{
  "场景描述": "中式夜宵烤肉串",
  "整体引导": "靠近前排肉串。降低相机高度。平视拍特写。虚化后方烤肉。",
  "摆盘描述": "前排肉串向中间靠拢。把大块烤肉层层叠放。签子末端向外散开。"
}

{
    "场景描述": "餐厅日式生牛肉",
    "整体引导": "大牛排移至前景。其他肉盘推远。降低镜头。呈三十度角近拍。",
    "摆盘描述": "大块牛排竹盘移至最前方。另两盘肉向左后推远，作为背景。"
}

{
    "场景描述": "潮汕牛肉火锅店",
    "整体引导": "将牛肉盘放前面。果汁放右后方。降低角度近拍。背景要虚化。",
    "摆盘描述": "肥牛肉盘移到最前。另一盘放左后。毛肚推到后方。果汁摆右后方。"
}

{
    "场景描述": "夜市档口烤肉串",
    "整体引导": "烤串整齐平放铁盘。手端铁盘靠近镜头。开启大光圈虚化背景。",
    "摆盘描述": "烤肉推至铁签前端。肉串紧密平行排列。整齐平放于铁盘中。"
}

{
    "场景描述": "木桌日料三文鱼",
    "整体引导": "选饱满春卷放盘前。镜头贴近盘子边缘。对焦首个春卷截面。",
    "摆盘描述": "挑切面饱满的春卷。放在黑色长盘前端。蔬菜切面朝向外侧。"
}

{
    "场景描述": "中式火锅鲜牛肉",
    "整体引导": "火锅居中。对焦火锅。45度俯拍。前后放肉盘，增加层次感。",
    "摆盘描述": "火锅放中央。酱料瓶放右侧。后方放肉和夹子。左下露出半盘肉。"
}

{
    "场景描述": "中餐厅红烧肉",
    "整体引导": "撤掉鸡蛋。镜头降低靠近。对焦前排酥肉。背景自然虚化。",
    "摆盘描述": "撤走鸡蛋盘子。酥肉拉到右下角。红烧肉放左上。汤碗往右后移。"
}

{
    "场景描述": "潮汕牛肉火锅店",
    "整体引导": "蘸料碗移近。夹肉停在碗上方。镜头拉近放大。对焦熟肉拍摄。",
    "摆盘描述": "肉盘放后方。蘸料碗移至右下。筷子夹起熟肉。停在碗左上方。"
}

{
    "场景描述": "街头铁板锅巴饭",
    "整体引导": "前置锅巴，压低镜头，大光圈虚化背景，对焦铲起的馅料。",
    "摆盘描述": "铲子挑起大量土豆丝，露出底部饱满米饭，前方放置金黄锅巴。"
}

{
    "场景描述": "木桌越南牛肉粉",
    "整体引导": "清走桌面的杂物小票。食物呈三角形摆放。向下四十五度俯拍。",
    "摆盘描述": "前方汤粉移至右下。后方汤碗向后推远。炸鸡米饭放在左侧。"
}

{
    "场景描述": "中式火锅调料台",
    "整体引导": "降机位微俯拍。靠近勺子小碗。对焦流出的油。虚化背景调料。",
    "摆盘描述": "左手端起小碗。右手举高勺子。倾斜勺子倒红油。碗在下方接住。"
}

{
    "场景描述": "中式烧烤西葫芦",
    "整体引导": "挑出两根烤串，移近镜头拍特写，置于画面右侧，虚化背景。",
    "摆盘描述": "拿两根西葫芦串，并排竖立在前。其他肉串放后方，作背景陪衬。"
}

{
    "场景描述": "大理石桌火锅肉",
    "整体引导": "肉片移至盘子右侧。盘子放画面右下角。镜头倾斜向下俯拍。",
    "摆盘描述": "将肉卷推至盘右侧。保持肉片紧密层叠。露出左侧青花纹理。"
}

{
    "场景描述": "中式木桌羊肉汤",
    "整体引导": "将羊肉聚在碗中央。手持木勺舀起肉块。保持微俯角拍摄。",
    "摆盘描述": "肉块集中在碗中央。顶部撒葱花与枸杞。后方摆放两个小碗。"
}

{
    "场景描述": "美式烤肉拼盘",
    "整体引导": "肉片叠放前方。降低拍摄角度。镜头贴近肉片。对焦切面纹理。",
    "摆盘描述": "牛腩切片叠放前方。手撕肉堆放在其后。香肠配菜放边缘。"
}

{
    "场景描述": "碗里的大闸蟹",
    "整体引导": "把螃蟹移到碗右侧。相机贴近碗的边缘。平视拍螃蟹的特写。",
    "摆盘描述": "把螃蟹移到碗右边。让螃蟹面朝左下方。展现出两只大螯。"
}

{
    "场景描述": "暗调红油老火锅",
    "整体引导": "镜头推近中间小锅。降低机位微俯拍。倒出宽厚的红油柱。",
    "摆盘描述": "中心小锅注满沸腾热油。外侧均匀铺满红辣椒。撒上几粒花椒。"
}

{
    "场景描述": "桌面火锅肥牛",
    "整体引导": "将肥牛移前方。降低镜头平拍。对焦在肉片上。虚化后方菜品。",
    "摆盘描述": "将肥牛移至左下方。红汤锅放在右下方。蔬菜拼盘推向后方。"
}

{
    "场景描述": "中式铁盘烤肉串",
    "整体引导": "拿掉底层垫膜。降低相机角度。靠近肉串特写。对焦前排肉块。",
    "摆盘描述": "去掉底部的塑料膜。将肉串重叠摆放。让蒜苔与肉块交错。"
}

{
    "场景描述": "铜炉火锅涮羊肉",
    "整体引导": "调暗环境光。铜锅烧开冒热气。用筷子夹肉卷。平视微俯拍。",
    "摆盘描述": "肉卷整齐铺碎冰上。左前方放多肉。右后插竹签。肉后立起标签。"
}

{
    "场景描述": "木桌韩式冷面",
    "整体引导": "撤走沙拉与空碗。泡菜放冷面右后方。降低镜头。斜向下拍。",
    "摆盘描述": "鸡蛋放面汤右上方。黄瓜丝围着面条放。用筷子夹起左侧面条。"
}

{
  "场景描述": "木纹桌韩式冷面",
  "整体引导": "前放冷面后放沙拉。斜向下四十五度拍。用筷子挑起冷面条。",
  "摆盘描述": "面条堆放在碗中间。左摆番茄右放泡菜。碗底铺满黄瓜香菜。"
}

{
  "场景描述": "木桌泰式海鲜面",
  "整体引导": "降低镜头斜拍。前景冷饮虚化。退后半步拍摄。配菜放锅两侧。",
  "摆盘描述": "筷子降低高度。只夹起少许面。大虾摆面条前。冷饮移至正前。"
}

{
    "场景描述": "餐厅韩式烤肉盘",
    "整体引导": "夹起一块烤肉。镜头降低靠近拍。对焦肉片，虚化后方酱料。",
    "摆盘描述": "烤肉向盘中间聚拢。挑出一块焦边肉，用筷子悬停在上方。"
}

{
    "场景描述": "桌面韩式冷面",
    "整体引导": "抽出筷子放下冷面。镜头后退露出碗边。向下四十五度俯拍。",
    "摆盘描述": "面条自然沉入碗底。牛肉片交叠放中间。右侧汤中加三块冰。"
}

{
    "场景描述": "日式寿司桌面",
    "整体引导": "拉远镜头拍全长盘。茶杯移至画面左侧。采用对角线构图。",
    "摆盘描述": "长盘向右上方斜放。刺身碗置于左上方。茶杯摆在长盘左侧。"
}

{
    "场景描述": "暗调麻辣小龙虾",
    "整体引导": "将枯枝拉低靠近龙虾。底部增加干冰烟雾。降低画面曝光。",
    "摆盘描述": "小龙虾紧凑地堆叠于盆中。顶部放香菜。表面撒匀白芝麻。"
}

{
    "场景描述": "木桌韩式拌饭",
    "整体引导": "清空杂物。小菜置于左下。降低机位，斜向近拍，虚化背景。",
    "摆盘描述": "拌饭碗居中摆放。小菜碟移至左下角，与大碗拉开些距离。"
}

{
    "场景描述": "韩式辣鸡爪餐厅",
    "整体引导": "夹起大鸡爪。左侧绿叶立起。降低镜头平拍。对焦在鸡爪上。",
    "摆盘描述": "用筷子夹起大鸡爪。停在半空作展示。左侧绿叶向上竖起。"
}

{
    "场景描述": "川渝九宫格火锅",
    "整体引导": "将火锅放正中间，配菜放四周。拉开距离，以四十五度角拍摄。",
    "摆盘描述": "将火锅放中间。鸭肠放在左上方，凤爪放在右下角，生菜放左侧。"
}

{
